/** Current placement scope of an immutable commit. */
export type CommitAvailability = "local" | "portable" | "unavailable";

/** Snapshot and NDJSON-follow event for primary-workload output. */
export type VmWorkloadLogEvent =
  | VmWorkloadLogEvent.Gap
  | VmWorkloadLogEvent.Chunk
  | VmWorkloadLogEvent.CaptureError
  | VmWorkloadLogEvent.Terminal
  | VmWorkloadLogEvent.End
;

export namespace VmWorkloadLogEvent {
  export interface Gap {
    available_cursor: number;
    dropped_bytes: number;
    log_id: string;
    requested_cursor: number;
    type: string;
  }

  export interface Chunk {
    cursor: number;
    /** Base64-encoded stdout/stderr bytes. */
    data_b64: string;
    log_id: string;
    next_cursor: number;
    stream: VmWorkloadLogStream;
    timestamp: string;
    type: string;
  }

  export interface CaptureError {
    cursor: number;
    error: VmWorkloadLogCaptureError;
    log_id: string;
    type: string;
  }

  export interface Terminal {
    capture_error: unknown;
    cursor: number;
    log_id: string;
    terminal: VmWorkloadLogTerminal;
    type: string;
  }

  export interface End {
    log_id: string;
    message: string;
    next_cursor: number;
    reason: VmWorkloadLogEndReason;
    type: string;
  }

}

/** Why a bounded follow response ended without a workload terminal event. */
export type VmWorkloadLogEndReason = "follow_timeout" | "guest_disconnected" | "guest_error";

